    // v9.77 PERF: Language-aware compact export.
    // Previously returned the full 1.1 MB UI_LABELS object (52 languages) on every require.
    // The browser had to keep all 52 language objects alive in memory even though only
    // one language is ever used per page session.
    //
    // Fix: detect the active Moodle page language from <html lang="..."> at module-eval
    // time (safe — Moodle always sets this in PHP before any JS runs), build a compact
    // object with only the active language + the English fallback, and return that.
    // The other 50 language objects have no references from the returned value and are
    // immediately eligible for garbage collection — reducing runtime heap from ~1.1 MB
    // to ~20-40 KB for the two languages actually needed.
    //
    // player5.js getLabel() already uses UI_LABELS[langCode] || UI_LABELS['en'], so
    // the returned shape is fully compatible.
    var _htmlLang = (typeof document !== 'undefined' && document.documentElement)
        ? (document.documentElement.lang || 'en')
        : 'en';
    // Normalise: Moodle may give 'en', 'en-AU', 'zh-CN', 'pt-BR', etc.
    // Try exact match first, then base language (e.g. 'en' for 'en-AU').
    var _activeLang = UI_LABELS[_htmlLang]
        ? _htmlLang
        : (UI_LABELS[_htmlLang.split('-')[0]] ? _htmlLang.split('-')[0] : 'en');
    var _compactLabels = {};
    _compactLabels[_activeLang] = UI_LABELS[_activeLang] || UI_LABELS['en'];
    if (_activeLang !== 'en') {
        _compactLabels['en'] = UI_LABELS['en'];
    }
    // v13.94.6: the narration table rides alongside the compact UI labels. Attached as a
    // non-enumerable property so getLabel()'s `UI_LABELS[langCode]` lookups and any
    // Object.keys() walk over the returned object are unaffected by its presence.
